  ('0009fdee-dbb7-402d-b498-69becfd46d49', '47406236-126d-40ef-bc0c-da2d14cc1df9', 1, 'in_app', 'id', 'Lisensi Kedaluwarsa', 'Lisensi fanmark "{{fanmark_name}}" Anda telah kedaluwarsa. ', 'Lisensi telah kedaluwarsa', NULL, 1, '2025-12-05T13:03:15.302054+00:00', '2025-12-31T04:13:10.360803+00:00'),
  ('09be4ead-fe4e-46dc-a602-2324b4e4e23b', 'b1c2d3e4-f5a6-7890-abcd-111111111111', 1, 'in_app', 'ko', '이전 신청을 받았습니다', '{{requester_name}}님으로부터 "{{fanmark_name}}"의 이전 신청을 받았습니다. 승인 또는 거부를 선택해 주세요.', '이전 신청 접수', NULL, 1, '2025-12-30T09:12:23.562201+00:00', '2025-12-30T09:12:23.562201+00:00'),
