  ('30ef428b-3547-4c92-be23-4c9fe411c168', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890', 1, 'in_app', 'id', 'Fanmark Dikembalikan', 'Anda telah mengembalikan fanmark "{{fanmark_name}}". Akan kedaluwarsa pada {{grace_expires_at}}. Pengaturan akses Anda akan dihapus saat kedaluwarsa.', 'Fanmark telah dikembalikan', NULL, 1, '2025-12-06T07:08:49.021235+00:00', '2025-12-30T07:52:16.040889+00:00'),
