  ('b95bf25e-72b2-45c8-a042-754d1984836e', '4ba5ee3e-4222-4001-9a9f-8e968b36e920', 1, 'in_app', 'en', 'Favorite Fanmark Available', 'Your favorite fanmark "{{fanmark_name}}" is available. Join the lottery by {{grace_expires_at}}!', 'Join the lottery to get your favorite fanmark', '{"required":["user_id","fanmark_id","fanmark_name"]}', 1, '2025-10-20T03:13:18.743821+00:00', '2025-12-30T07:47:48.762547+00:00'),
