  ('ce6d270c-6daa-4d2c-894f-9947c48b5fd2', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890', 1, 'in_app', 'en', 'Fanmark Returned', 'You have returned fanmark "{{fanmark_name}}". It will expire on {{grace_expires_at}}. Your access settings will be deleted upon expiration.', 'Fanmark has been returned', NULL, 1, '2025-12-06T07:08:49.021235+00:00', '2025-12-30T07:52:16.040889+00:00'),
