  ('d081b32c-d382-40c2-90d0-a4971d925d52', 'efa32487-428f-4bb8-b4b3-90b5544e001a', 1, 'in_app', 'id', 'Masa Tenggang Lisensi Dimulai', 'Lisensi fanmark "{{fanmark_name}}" sedang dalam masa tenggang. Perbarui sebelum {{grace_expires_at}}. Setelah batas waktu, pengaturan akses Anda akan dihapus dan tidak dapat dipulihkan.', 'Perpanjangan lisensi diperlukan', NULL, 1, '2025-12-05T13:03:15.302054+00:00', '2025-12-30T07:04:25.110251+00:00'),
  ('d5a0787e-a1a0-4fc4-a8cd-199b5e004043', 'b1c2d3e4-f5a6-7890-abcd-333333333333', 1, 'in_app', 'en', 'Transfer Request Rejected', 'Your transfer request for "{{fanmark_name}}" has been rejected.', 'Transfer rejected', NULL, 1, '2025-12-30T09:12:23.562201+00:00', '2025-12-30T09:12:23.562201+00:00'),
